unordered_map<int, int> mp;
int get_state(int a[]) {
  int state = 0;
  for (int i = 0; i < n; i++) state = 6 * state + a[i] - 1;
  return state;
}
void decode_state(int maps[], int state) {
  for (int i = n - 1; i >= 0; i--) {
    maps[i] = state % 6 + 1;
    state /= 6;
  }
}
void dfs(int pos, int group) {
  stage++;
  if (group > min(6, r) || pos + flag > n) return;
  if (pos == n) {
    int id = get_state(maps);
    int sz = mp.size();
    mp[id] = sz;
    rev[sz] = id;
    if ((group == r || group * 2 == n) && check()) {
      vis[sz] = true;
    }
    return;
  }
  c[group + 1]++;
  flag++;
  maps[pos] = group + 1;
  dfs(pos + 1, group + 1);
  flag--;
  c[group + 1]--;
  for (int i = 1; i <= group; i++) {
    c[i]++;
    if (c[i] & 1)
      flag++;
    else
      flag--;
    maps[pos] = i;
    dfs(pos + 1, group);
    if (c[i] & 1)
      flag--;
    else
      flag++;
    c[i]--;
  }
}
