    PushDown(t, l, r);
    if (p <= l && r <= q) {
      x[t] += a;
      sum[t] += (r - l + 1LL) * a;
      return;
    }
    int mid = (l + r) >> 1;
    if (p <= mid) Insert(t + t, a, l, mid, p, q);
    if (mid + 1 <= q) Insert(t + t + 1, a, mid + 1, r, p, q);
    sum[t] = sum[t + t] + sum[t + t + 1];
  }
